import { parseTest20Arguments, writeArgumentParserError } from './lib/cli/parser.mjs';
import { formatPythonAsciiBytes, formatPythonBytes, writeLine } from './lib/format/python.mjs';

function main() {
  const programName = basename(process.argv[1] ?? 'test20.mjs');
  let parsedArguments;

  try {
    parsedArguments = parseTest20Arguments(process.argv.slice(2), programName);
  } catch (error) {
    writeArgumentParserError(programName, error.message, process.stderr);
    process.exit(2);
  }

  if (parsedArguments.kind === 'help') {
    writeLine(process.stdout, parsedArguments.text);
    return;
  }

  const args = parsedArguments.values;

  const enc1 = b58encode(toUtf8Bytes(args.a));
  const dec1 = b58decode(args.b);
  const encCheck1 = b58encodeCheck(toUtf8Bytes(args.c));
  const decCheck1 = b58decodeCheck(encCheck1);
  const encInt1 = b58encodeInt(args.f);
  const decInt1 = b58decodeInt(encInt1);
  const enc2 = b58encode(toUtf8Bytes(args.d));
  const dec2 = b58decode(args.e);
  const encInt2 = b58encodeInt(args.g);
  const encCheck2 = b58encodeCheck(dec1);
  const decCheck2 = b58decodeCheck(encCheck2);
  const enc3 = b58encode(decCheck2);

  writeLine(process.stdout, formatPythonAsciiBytes(enc1));
  writeLine(process.stdout, formatPythonBytes(dec1));
  writeLine(process.stdout, formatPythonAsciiBytes(encCheck1));
  writeLine(process.stdout, formatPythonBytes(decCheck1));
  writeLine(process.stdout, formatPythonAsciiBytes(encInt1));
  writeLine(process.stdout, decInt1.toString());
  writeLine(process.stdout, formatPythonAsciiBytes(enc2));
  writeLine(process.stdout, formatPythonBytes(dec2));
  writeLine(process.stdout, formatPythonAsciiBytes(encInt2));
  writeLine(process.stdout, formatPythonAsciiBytes(encCheck2));
  writeLine(process.stdout, formatPythonBytes(decCheck2));
  writeLine(process.stdout, formatPythonAsciiBytes(enc3));
