const ARGUMENT_DEFINITIONS = [
  { long: '--a', key: 'a', metavar: 'A', type: 'string', required: true },
  { long: '--b', key: 'b', metavar: 'B', type: 'string', required: true },
  { long: '--c', key: 'c', metavar: 'C', type: 'string', required: true },
  { long: '--d', key: 'd', metavar: 'D', type: 'string', required: true },
  { long: '--e', key: 'e', metavar: 'E', type: 'string', required: true },
  { long: '--f', key: 'f', metavar: 'F', type: 'int', required: true },
  { long: '--g', key: 'g', metavar: 'G', type: 'int', required: true },
];

const LONG_OPTION_DEFINITIONS = [
  { long: '--help', type: 'help' },
  ...ARGUMENT_DEFINITIONS,
];

const EXACT_LONG_OPTION_MAP = new Map(
  LONG_OPTION_DEFINITIONS.map((definition) => [definition.long, definition]),
