function parsePythonInt(text) {
  if (!/^[+-]?(?:\d(?:_?\d)*)$/.test(text)) {
    return null;
  }

  return BigInt(text.replaceAll('_', ''));
}

function isNegativeIntegerToken(text) {
  return parsePythonInt(text) !== null && text.startsWith('-');
}

function resolveLongOption(tokenName) {
  if (EXACT_LONG_OPTION_MAP.has(tokenName)) {
    return EXACT_LONG_OPTION_MAP.get(tokenName);
  }

  const matches = LONG_OPTION_DEFINITIONS.filter((definition) => definition.long.startsWith(tokenName));

  if (matches.length === 1) {
    return matches[0];
  }

  return null;
