export function parseTest20Arguments(argv, programName) {
  const values = {};
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h') {
      return { kind: 'help', text: formatHelp(programName) };
    }

    if (token === '--') {
      extras.push(...argv.slice(index + 1));
      break;
    }

    if (token.startsWith('--')) {
      const equalsIndex = token.indexOf('=');
      const optionName = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
      const optionDefinition = resolveLongOption(optionName);

      if (optionDefinition === null) {
        extras.push(token);
        continue;
      }

      if (optionDefinition.type === 'help') {
        if (equalsIndex !== -1) {
          throw createError(programName, `argument --help: ignored explicit argument: '${token.slice(equalsIndex + 1)}'`);
        }

        return { kind: 'help', text: formatHelp(programName) };
      }

      let rawValue;

      if (equalsIndex !== -1) {
        rawValue = token.slice(equalsIndex + 1);
      } else {
        const nextToken = argv[index + 1];

        if (
          nextToken === undefined
          || nextToken === '--'
          || (nextToken.startsWith('-') && !(optionDefinition.type === 'int' && isNegativeIntegerToken(nextToken)))
        ) {
          throw createError(programName, `argument ${optionDefinition.long}: expected one argument`);
        }

        rawValue = nextToken;
        index += 1;
