      if (optionDefinition.type === 'int') {
        const parsedValue = parsePythonInt(rawValue);

        if (parsedValue === null) {
          throw createError(programName, `argument ${optionDefinition.long}: invalid int value: '${rawValue}'`);
        }

        values[optionDefinition.key] = parsedValue;
        continue;
      }

      values[optionDefinition.key] = rawValue;
      continue;
    }

    extras.push(token);
  }

  const missingArguments = ARGUMENT_DEFINITIONS
    .filter((definition) => definition.required && !(definition.key in values))
    .map((definition) => definition.long);

  if (missingArguments.length > 0) {
    throw createError(
      programName,
      `the following arguments are required: ${missingArguments.join(', ')}`,
    );
  }

  if (extras.length > 0) {
    throw createError(programName, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return { kind: 'values', values };
