function selectQuote(bytes) {
  const hasSingleQuote = bytes.includes(0x27);
  const hasDoubleQuote = bytes.includes(0x22);

  if (hasSingleQuote && !hasDoubleQuote) {
    return '"';
  }

  return "'";
}

export function formatPythonBytes(bytes) {
  const quote = selectQuote(bytes);
  const quoteCode = quote.charCodeAt(0);
  let body = '';

  for (const byte of bytes) {
    if (byte === quoteCode) {
      body += `\\${quote}`;
      continue;
    }

    if (byte === 0x5c) {
      body += '\\\\';
      continue;
    }

    if (byte === 0x09) {
      body += '\\t';
      continue;
    }

    if (byte === 0x0a) {
      body += '\\n';
      continue;
    }

    if (byte === 0x0d) {
      body += '\\r';
      continue;
    }

    if (byte >= 0x20 && byte <= 0x7e) {
      body += String.fromCharCode(byte);
      continue;
    }

    body += `\\x${byte.toString(16).padStart(2, '0')}`;
  }

  return `b${quote}${body}${quote}`;
}

export function formatPythonAsciiBytes(text) {
  return formatPythonBytes(latin1StringToBytes(text));
