function divmodFloor(dividend, divisor) {
  let remainder = dividend % divisor;

  if (remainder < 0n) {
    remainder += divisor;
  }

  const quotient = (dividend - remainder) / divisor;
  return { quotient, remainder };
}

export function b58encode(bytes) {
  if (bytes.length === 0) {
    return '';
  }

  let leadingZeroCount = 0;

  while (leadingZeroCount < bytes.length && bytes[leadingZeroCount] === 0) {
    leadingZeroCount += 1;
  }

  let value = 0n;

  for (const byte of bytes) {
    value = (value * 256n) + BigInt(byte);
  }

  let encoded = '';

  while (value > 0n) {
    const remainder = Number(value % 58n);
    encoded = BASE58_ALPHABET[remainder] + encoded;
    value /= 58n;
  }

  return `${BASE58_ALPHABET[0].repeat(leadingZeroCount)}${encoded}`;
}

export function b58decode(text) {
  if (text.length === 0) {
    return [];
  }

  let leadingOneCount = 0;

  while (leadingOneCount < text.length && text[leadingOneCount] === BASE58_ALPHABET[0]) {
    leadingOneCount += 1;
  }

  let value = 0n;

  for (const character of text) {
    if (!BASE58_INDEX.has(character)) {
      throw new Error(`Invalid character '${character}'`);
    }

    value = (value * 58n) + BigInt(BASE58_INDEX.get(character));
  }

  const decoded = [];

  while (value > 0n) {
    decoded.push(Number(value % 256n));
    value /= 256n;
  }

  decoded.reverse();

  return [
    ...Array.from({ length: leadingOneCount }, () => 0),
    ...decoded,
  ];
