  let current = BigInt(value);
  let encoded = '';

  while (current !== 0n) {
    const { quotient, remainder } = divmodFloor(current, 58n);
    encoded = BASE58_ALPHABET[Number(remainder)] + encoded;
    current = quotient;
  }

  if (encoded === '') {
    return BASE58_ALPHABET[0];
  }

  return encoded;
}

