export function toUtf8Bytes(text) {
  const bytes = [];

  for (let index = 0; index < text.length; index += 1) {
    const codeUnit = text.charCodeAt(index);

    if (codeUnit >= 0xd800 && codeUnit <= 0xdbff) {
      const nextCodeUnit = text.charCodeAt(index + 1);

      if (!(nextCodeUnit >= 0xdc00 && nextCodeUnit <= 0xdfff)) {
        throw new RangeError('Unpaired high surrogate in input string');
      }

      const codePoint =
        ((codeUnit - 0xd800) << 10) + (nextCodeUnit - 0xdc00) + 0x10000;

      bytes.push(
        0xf0 | (codePoint >> 18),
        0x80 | ((codePoint >> 12) & 0x3f),
        0x80 | ((codePoint >> 6) & 0x3f),
        0x80 | (codePoint & 0x3f),
      );

      index += 1;
      continue;
    }

    if (codeUnit >= 0xdc00 && codeUnit <= 0xdfff) {
      throw new RangeError('Unpaired low surrogate in input string');
    }

    if (codeUnit <= 0x7f) {
      bytes.push(codeUnit);
      continue;
    }

    if (codeUnit <= 0x7ff) {
      bytes.push(
        0xc0 | (codeUnit >> 6),
        0x80 | (codeUnit & 0x3f),
      );
      continue;
    }

    bytes.push(
      0xe0 | (codeUnit >> 12),
      0x80 | ((codeUnit >> 6) & 0x3f),
      0x80 | (codeUnit & 0x3f),
    );
  }

  return bytes;
}

