  { name: 'g', flag: '--g', metavar: 'G', type: 'int' },
];

const OPTION_MAP = new Map(OPTION_DEFINITIONS.map((definition) => [definition.flag, definition]));

function normalizeProgramName(programPath) {
  return basename(programPath || 'test20.mjs');
}

function isKnownOptionToken(token) {
  if (token === '-h' || token === '--help') {
    return true;
  }
  if (!token.startsWith('--')) {
    return false;
  }
  const separatorIndex = token.indexOf('=');
  const flag = separatorIndex === -1 ? token : token.slice(0, separatorIndex);
  return OPTION_MAP.has(flag);
}

function parseLongOptionToken(token) {
  if (!token.startsWith('--')) {
    return null;
  }

  const separatorIndex = token.indexOf('=');
  if (separatorIndex === -1) {
    return {
      flag: token,
      hasInlineValue: false,
      inlineValue: '',
    };
  }

  return {
    flag: token.slice(0, separatorIndex),
    hasInlineValue: true,
    inlineValue: token.slice(separatorIndex + 1),
  };
}

function parseInteger(flag, rawValue, programName) {
  if (!/^[+-]?\d+$/.test(rawValue)) {
    throw new CLIParseError(programName, `argument ${flag}: invalid int value: '${rawValue}'`);
  }
  return BigInt(rawValue);
}

export class CLIParseError extends Error {
  constructor(programName, message) {
    super(message);
    this.name = 'CLIParseError';
    this.programName = programName;
  }
}

export function usageText(programPath) {
  const programName = normalizeProgramName(programPath);
  return `usage: ${programName} [-h] --a A --b B --c C --d D --e E --f F --g G`;
}

export function helpText(programPath) {
  const programName = normalizeProgramName(programPath);
  return `${usageText(programName)}

options:
  -h, --help  show this help message and exit
  --a A
  --b B
  --c C
  --d D
  --e E
  --f F
  --g G`;
