export function parseCommandLine(argv, programPath) {
  const programName = normalizeProgramName(programPath);
  const values = {};
  const extras = [];
  let helpRequested = false;

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      helpRequested = true;
      continue;
    }

    if (token === '--') {
      extras.push(...argv.slice(index + 1));
      break;
    }

    const optionToken = parseLongOptionToken(token);
    if (optionToken && OPTION_MAP.has(optionToken.flag)) {
      const definition = OPTION_MAP.get(optionToken.flag);

      let rawValue;
      if (optionToken.hasInlineValue) {
        rawValue = optionToken.inlineValue;
      } else {
        const nextToken = argv[index + 1];
        if (nextToken === undefined || nextToken === '--' || isKnownOptionToken(nextToken)) {
          throw new CLIParseError(programName, `argument ${optionToken.flag}: expected one argument`);
        }
        rawValue = nextToken;
        index += 1;
      }

      values[definition.name] = definition.type === 'int'
        ? parseInteger(optionToken.flag, rawValue, programName)
        : rawValue;
      continue;
    }

    if (optionToken) {
      extras.push(token);
      const nextToken = argv[index + 1];
      if (!optionToken.hasInlineValue && nextToken !== undefined && nextToken !== '--' && !nextToken.startsWith('-')) {
        extras.push(nextToken);
        index += 1;
      }
      continue;
    }

    extras.push(token);
  }

  if (helpRequested) {
    return { kind: 'help', programName };
  }

  const missingFlags = OPTION_DEFINITIONS
    .filter((definition) => !Object.prototype.hasOwnProperty.call(values, definition.name))
    .map((definition) => definition.flag);

  if (missingFlags.length > 0) {
    throw new CLIParseError(programName, `the following arguments are required: ${missingFlags.join(', ')}`);
  }

  if (extras.length > 0) {
    throw new CLIParseError(programName, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return {
    kind: 'values',
    programName,
    values,
  };
}

