  for (const value of values) {
    sum = (sum + (value >>> 0)) >>> 0;
  }
  return sum;
}

function rotateRight(value, shift) {
  return ((value >>> shift) | (value << (32 - shift))) >>> 0;
}

function choose(x, y, z) {
  return ((x & y) ^ (~x & z)) >>> 0;
}

function majority(x, y, z) {
  return ((x & y) ^ (x & z) ^ (y & z)) >>> 0;
}

function sigma0(value) {
  return (rotateRight(value, 7) ^ rotateRight(value, 18) ^ (value >>> 3)) >>> 0;
}

function sigma1(value) {
  return (rotateRight(value, 17) ^ rotateRight(value, 19) ^ (value >>> 10)) >>> 0;
}

function bigSigma0(value) {
  return (rotateRight(value, 2) ^ rotateRight(value, 13) ^ rotateRight(value, 22)) >>> 0;
}

function bigSigma1(value) {
  return (rotateRight(value, 6) ^ rotateRight(value, 11) ^ rotateRight(value, 25)) >>> 0;
}

function writeUint64BigEndian(bytes, bitLength) {
  const out = bytes.slice();
  for (let shift = 56n; shift >= 0n; shift -= 8n) {
    out.push(Number((bitLength >> shift) & 0xffn));
  }
  return out;
}

function toWords(block) {
  const words = new Array(64).fill(0);

  for (let index = 0; index < 16; index += 1) {
    const offset = index * 4;
    words[index] = (
      (block[offset] << 24)
      | (block[offset + 1] << 16)
      | (block[offset + 2] << 8)
      | block[offset + 3]
    ) >>> 0;
  }

  for (let index = 16; index < 64; index += 1) {
    words[index] = add32(
      sigma1(words[index - 2]),
      words[index - 7],
      sigma0(words[index - 15]),
      words[index - 16],
    );
  }

  return words;
}

export function sha256(bytes) {
  const hash = INITIAL_HASH.slice();
  const bitLength = BigInt(bytes.length) * 8n;

  let message = bytes.slice();
  message.push(0x80);

  while ((message.length % 64) !== 56) {
    message.push(0x00);
  }

  message = writeUint64BigEndian(message, bitLength);

  for (let offset = 0; offset < message.length; offset += 64) {
    const block = message.slice(offset, offset + 64);
    const words = toWords(block);

    let a = hash[0];
    let b = hash[1];
    let c = hash[2];
    let d = hash[3];
    let e = hash[4];
    let f = hash[5];
    let g = hash[6];
    let h = hash[7];

    for (let round = 0; round < 64; round += 1) {
      const temp1 = add32(
        h,
        bigSigma1(e),
        choose(e, f, g),
        ROUND_CONSTANTS[round],
        words[round],
      );
      const temp2 = add32(bigSigma0(a), majority(a, b, c));

      h = g;
      g = f;
      f = e;
      e = add32(d, temp1);
      d = c;
      c = b;
      b = a;
      a = add32(temp1, temp2);
    }

    hash[0] = add32(hash[0], a);
    hash[1] = add32(hash[1], b);
    hash[2] = add32(hash[2], c);
    hash[3] = add32(hash[3], d);
    hash[4] = add32(hash[4], e);
    hash[5] = add32(hash[5], f);
    hash[6] = add32(hash[6], g);
    hash[7] = add32(hash[7], h);
  }

  const digest = [];
  for (const word of hash) {
    digest.push((word >>> 24) & 0xff);
    digest.push((word >>> 16) & 0xff);
    digest.push((word >>> 8) & 0xff);
    digest.push(word & 0xff);
  }

  return digest;
}

import { basename } from 'node:path';
import { pathToFileURL } from 'node:url';

import {
  b58encode,
  b58decode,
  b58encodeCheck,
  b58decodeCheck,
  b58encodeInt,
  b58decodeInt,
  toUtf8Bytes,
} from './lib/base58/index.mjs';
import { parseTest20Arguments, writeArgumentParserError } from './lib/cli/parser.mjs';
import { formatPythonAsciiBytes, formatPythonBytes, writeLine } from './lib/format/python.mjs';

export function main(argv = process.argv.slice(2), scriptPath = process.argv[1]) {
  const programName = basename(scriptPath ?? 'test20.mjs');
  let parsedArguments;

  try {
    parsedArguments = parseTest20Arguments(argv, programName);
  } catch (error) {
    writeArgumentParserError(programName, error.message, process.stderr);
    return 2;
  }

  if (parsedArguments.kind === 'help') {
    writeLine(process.stdout, parsedArguments.text);
    return 0;
  }

  const args = parsedArguments.values;

  const enc1 = b58encode(toUtf8Bytes(args.a));
  const dec1 = b58decode(args.b);
  const encCheck1 = b58encodeCheck(toUtf8Bytes(args.c));
  const decCheck1 = b58decodeCheck(encCheck1);
  const encInt1 = b58encodeInt(args.f);
  const decInt1 = b58decodeInt(encInt1);
  const enc2 = b58encode(toUtf8Bytes(args.d));
  const dec2 = b58decode(args.e);
  const encInt2 = b58encodeInt(args.g);
  const encCheck2 = b58encodeCheck(dec1);
  const decCheck2 = b58decodeCheck(encCheck2);
  const enc3 = b58encode(decCheck2);

  writeLine(process.stdout, formatPythonAsciiBytes(enc1));
  writeLine(process.stdout, formatPythonBytes(dec1));
  writeLine(process.stdout, formatPythonAsciiBytes(encCheck1));
  writeLine(process.stdout, formatPythonBytes(decCheck1));
  writeLine(process.stdout, formatPythonAsciiBytes(encInt1));
  writeLine(process.stdout, decInt1.toString());
  writeLine(process.stdout, formatPythonAsciiBytes(enc2));
  writeLine(process.stdout, formatPythonBytes(dec2));
  writeLine(process.stdout, formatPythonAsciiBytes(encInt2));
  writeLine(process.stdout, formatPythonAsciiBytes(encCheck2));
  writeLine(process.stdout, formatPythonBytes(decCheck2));
  writeLine(process.stdout, formatPythonAsciiBytes(enc3));

  return 0;
}

const entryPoint = process.argv[1] ? pathToFileURL(process.argv[1]).href : '';
if (entryPoint === import.meta.url) {
  process.exitCode = main();
}

import { createHash } from 'node:crypto';

import { bytesToLatin1String, latin1StringToBytes } from './bytes.mjs';

export function sha256(bytes) {
  const digest = createHash('sha256')
    .update(bytesToLatin1String(bytes), 'latin1')
    .digest('latin1');

  return latin1StringToBytes(digest);
}

export function doubleSha256(bytes) {
  return sha256(sha256(bytes));
}
